CREATE TABLE control (
  key TEXT PRIMARY KEY CHECK (key IN ('money_pause', 'switch_at_ms', 'migration_open', 'dev_fault')),
  value TEXT NOT NULL,
  updated_at_ms INTEGER NOT NULL,
  updated_by TEXT NOT NULL
) STRICT;
INSERT INTO control (key, value, updated_at_ms, updated_by) VALUES
  ('money_pause', '0', 0, 'migration'),
  ('migration_open', '0', 0, 'migration');

INSERT INTO ledger (id, user_id, type, amount, reason, source, balance_after, idem_key, created_at_ms, meta_json)
SELECT :id, :uid, 'opening', :amount, :reason, :source, :amount, 'open:' || :uid, :now, :meta
 WHERE NOT EXISTS (SELECT 1 FROM balances WHERE user_id = :uid)
   AND EXISTS (SELECT 1 FROM control WHERE key = 'money_pause' AND value = '0');
INSERT INTO balances (user_id, balance, created_at_ms, updated_at_ms, opened_via, kv_last_updated)
SELECT :uid, :amount, :now, :now, :via, :kv_last
 WHERE EXISTS (SELECT 1 FROM ledger WHERE id = :id);
SELECT (SELECT balance FROM balances WHERE user_id = :uid)  AS balance,
       (SELECT id FROM ledger WHERE id = :id)                AS opened_now,
       (SELECT value FROM control WHERE key = 'money_pause') AS pause_value;

SELECT j.user_id, j.request_hash, j.provenance, j.state, j.outcome,
       (SELECT id FROM ledger WHERE idem_key = 'debit:' || j.job_id) AS debit_id
  FROM jobs AS j WHERE j.job_id = :job;

SELECT j.claim_id, j.released_at_ms, j.finished_at_ms, j.submitted_at_ms, j.task_id, j.phase,
       j.artifact, j.lease_at_ms
  FROM jobs AS j WHERE j.job_id = :job;

-- the first unresolved delivery
INSERT INTO stripe_pending (event_id, reason, first_seen_ms) VALUES (:event, :reason, :now)
ON CONFLICT (event_id) DO NOTHING;
-- George's disposition for a 'no_evidence' event (G); a 'none' past Stripe's resend limits carries its note (4.18)
UPDATE stripe_pending SET disposition = :disposition, evidence_note = :note, decided_by = :who, decided_at_ms = :now
 WHERE event_id = :event AND reason = 'no_evidence' AND disposition IS NULL
   AND (:disposition IS NOT 'none' OR NOT EXISTS (SELECT 1 FROM ledger WHERE idem_key = 'stripe:' || :event));
-- N14: George's evidenced 'none' for a 'mapping_missing' charge he confirmed in Stripe is not a SpriteBrew purchase (G)
UPDATE stripe_pending SET disposition = 'none', evidence_note = :note, decided_by = :who, decided_at_ms = :now
 WHERE event_id = :event AND reason = 'mapping_missing' AND disposition IS NULL
   AND NOT EXISTS (SELECT 1 FROM ledger WHERE idem_key = 'stripe:' || :event);
SELECT disposition, (SELECT COUNT(*) FROM ledger WHERE idem_key = 'stripe:' || :event) AS moved
  FROM stripe_pending WHERE event_id = :event;

UPDATE control SET value = '1', updated_at_ms = :now, updated_by = :who WHERE key = 'money_pause' AND value = '0';
UPDATE control SET value = '0', updated_at_ms = :now, updated_by = :who WHERE key = 'money_pause' AND value = '1'
   AND NOT EXISTS (SELECT 1 FROM switch_drift WHERE disposition IS NULL)
   AND (EXISTS (SELECT 1 FROM control WHERE key = 'switch_at_ms' AND value = '99999999999999')   -- release 1: no backstop
        OR EXISTS (SELECT 1 FROM backstop_runs WHERE purpose = 'close' AND complete = 1)        -- after Close
        OR EXISTS (SELECT 1 FROM backstop_runs
                    WHERE complete = 1
                      AND run_pause_ms = (SELECT updated_at_ms FROM control WHERE key = 'money_pause' AND value = '1')));
SELECT key, value, updated_at_ms FROM control WHERE key = 'money_pause';

UPDATE switch_obligations SET paid_evidence_json = :evidence, paid_found_at_ms = :now
 WHERE subject_kind = :kind AND subject_id = :subject AND disposition = 'carry'
   AND settled_at_ms IS NULL AND paid_found_at_ms IS NULL;
SELECT pause_epoch_ms, paid_found_at_ms FROM switch_obligations WHERE subject_kind = :kind AND subject_id = :subject;

-- S0: admission, before the first money write
INSERT INTO money_admissions (admission_id, route, subject_kind, subject_id, user_id, meta_json, admitted_at_ms)
SELECT :admission, :route, :kind, :subject, :uid, :meta, :now
 WHERE EXISTS (SELECT 1 FROM control WHERE key = 'money_pause' AND value = '0');
SELECT admission_id FROM money_admissions WHERE admission_id = :admission;
-- S0: completion, in the finally; kept beside a closure (R7-1)
UPDATE money_admissions SET completed_at_ms = :now WHERE admission_id = :admission AND completed_at_ms IS NULL;
SELECT completed_at_ms, closed_at_ms FROM money_admissions WHERE admission_id = :admission;

UPDATE control SET value = :to, updated_at_ms = :now, updated_by = :who
 WHERE key = 'migration_open' AND value = :from
   AND :from || '>' || :to IN ('0>scan', 'scan>0', 'scan>snapshot', 'snapshot>verify', 'snapshot>0', 'verify>0')
   AND (:to NOT IN ('snapshot', 'verify')
        OR EXISTS (SELECT 1 FROM control WHERE key = 'money_pause' AND value = '1'));
SELECT value FROM control WHERE key = 'migration_open';

-- step 2, first command: the pause
UPDATE control SET value = '1', updated_at_ms = :cutoff, updated_by = 'switch'
 WHERE key = 'money_pause' AND value = '0';
-- step 2, second command: the cutoff, written once and never overwritten
INSERT INTO switch_marks (name, value_ms, recorded_at_ms)
SELECT 'pause_start_ms', :cutoff, :cutoff
 WHERE EXISTS (SELECT 1 FROM control WHERE key = 'money_pause' AND value = '1' AND updated_at_ms = :cutoff)
ON CONFLICT (name) DO NOTHING;
SELECT (SELECT updated_at_ms FROM control WHERE key = 'money_pause' AND value = '1') AS pause_epoch_ms,
       (SELECT value_ms FROM switch_marks WHERE name = 'pause_start_ms')            AS cutoff_ms;

-- George's review of a completion after his closure (G), before the next switch's step 0
UPDATE money_admissions
   SET late_review = :review, late_review_note = :note, late_reviewed_by = :who, late_reviewed_at_ms = :now
 WHERE admission_id = :admission AND closed_at_ms IS NOT NULL AND completed_at_ms IS NOT NULL
   AND late_review IS NULL;
SELECT late_review, completed_at_ms, closed_at_ms FROM money_admissions WHERE admission_id = :admission;
-- step 0: no completion after a closure is waiting for its review
SELECT COUNT(*) AS late_unreviewed FROM money_admissions
 WHERE closed_at_ms IS NOT NULL AND completed_at_ms IS NOT NULL AND late_review IS NULL;
